const req = $('Approvals List Webhook').first().json;
const key = $input.first().json || {};
const rid = 'req_' + $execution.id;
const fail = (status, code, message) => [{ json: { valid: false, status_code: status, response: { ok: false, request_id: rid, error: { code, message } } } }];
if (!key.api_key || key.active !== true || !['hr', 'hr_admin'].includes(key.client)) return fail(401, 'UNAUTHORIZED', 'Missing or invalid API key for this endpoint');
const q = req.query || {};
const errors = [];
for (const k of Object.keys(q)) if (!['status', 'type', 'limit'].includes(k)) errors.push('unknown query parameter: ' + k);
const status = q.status ? String(q.status) : 'pending_approval';
if (!['pending_approval', 'approved', 'sent', 'recorded', 'rejected', 'failed'].includes(status)) errors.push('status must be pending_approval, approved, sent, recorded, rejected or failed');
const type = q.type ? String(q.type) : '';
if (type && !['broadcast', 'ticket_reply', 'points_award'].includes(type)) errors.push('type must be broadcast, ticket_reply or points_award');
const limit = q.limit ? Number(q.limit) : 20;
if (!Number.isInteger(limit) || limit < 1 || limit > 50) errors.push('limit must be an integer from 1 to 50');
if (errors.length) return fail(400, 'VALIDATION_ERROR', errors.join('; '));
return [{ json: { valid: true, request_id: rid, status, type, limit } }];

const v = $('Authorize and Validate').first().json;
const parse = (s) => { try { return JSON.parse(s || '{}'); } catch (e) { return {}; } };
const now = Date.now();
const rows = $input.all().map(i => i.json).filter(r => r.approval_id && (!v.type || r.type === v.type));
const items = rows.slice(0, v.limit).map(r => {
  const p = parse(r.payload);
  const c = parse(r.checks);
  const details = Object.assign({}, p);
  delete details.draft;
  delete details.ai_draft;
  return {
    approval_id: r.approval_id,
    type: r.type,
    status: r.status,
    target: r.target_ref,
    created_by: r.created_by,
    created_at: r.createdAt,
    decided_by: r.decided_by || null,
    decided_at: r.decided_at || null,
    edited_by_human: r.edited_by_human === true,
    reason: r.reason || null,
    draft: p.draft || null,
    details,
    checks: c.checks || null,
    security: { injection_suspected: (c.flags || []).some(f => f.field !== 'model'), flags: c.flags || [], review_flag: c.review_flag || null },
    stale: r.status === 'pending_approval' && r.createdAt ? (now - Date.parse(r.createdAt)) > 72 * 3600 * 1000 : false
  };
});
return [{ json: { status_code: 200, response: { ok: true, request_id: v.request_id, data: { count: items.length, items } } } }];
